/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    boolean ret;

    ret = super();

    return ret;
}

/// <summary>
/// standard find method
/// </summary>
/// <param name = "_jourName">Journal name</param>
/// <param name = "_forUpdate">true/false</param>
/// <returns>Returns <c>METInventJournalParameters</c></returns>
static METInventJournalParameters find(InventJournalNameTransfer   _jourName,
                      boolean       _forUpdate = false)
{
    METInventJournalParameters parameters;

    if (_jourName)
    {
        if (_forUpdate)
        {
            parameters.selectForUpdate(_forUpdate);
        }

        select firstonly parameters
            index hint METMovementJournalNameIdIdx
            where parameters.TransferJournalNameId == _jourName;
    }

    return parameters;
}

/// <summary>
/// standard exist method
/// </summary>
/// <param name = "_jourName">Journal name</param>
/// <returns>Returns true/false</returns>
static boolean exist(InventJournalNameTransfer _jourName)
{
    return _jourName && (select firstonly RecId from mETInventJournalParameters
                                index hint METMovementJournalNameIdIdx
                                where METInventJournalParameters.TransferJournalNameId == _jourName).RecId != 0;
}
